return [{
  json: item.body
}];

// n8n Code node - Run Once for All Items
const googleDocsRegex = /^https:\/\/docs\.google\.com\/document\/d\/[a-zA-Z0-9_-]+(\/.*)?$/;

return items.map(item => {
  const user = item.json.user;
  const listName = item.json.listName;
  const docLink = item.json.docLink;

  const isUserValid = typeof user === 'string' && user.trim() !== '';
  const isListNameValid = typeof listName === 'string' && listName.trim() !== '';
  const isDocLinkValid = typeof docLink === 'string' && googleDocsRegex.test(docLink.trim());

  const valid = isUserValid && isListNameValid && isDocLinkValid;

  return {
    json: {
      user,
      listName,
      docLink,
      valid
    }
  };
});

