const items = $input.all();

return items.map(item => {
  return {
    json: {
      user: item.json.user,
      listName: item.json.listName,
      docLink: item.json.docLink
    }
  };
});

const previousNodeItems = $input.all();
const previousPreviousNodeItems = $('ABDUL: GET PREVIOUS NODE DATA').all();

const matchedResults = [];
const unmatchedResults = [];

for (const prevItem of previousNodeItems) {
  const displayName = (prevItem.json.displayName || '')
    .toString()
    .trim()
    .toLowerCase();

  const matchedItem = previousPreviousNodeItems.find(prevPrevItem => {
    const listName = (prevPrevItem.json.listName || '')
      .toString()
      .trim()
      .toLowerCase();
    return displayName === listName;
  });

  if (matchedItem) {
    matchedResults.push({
      json: {
        ...prevItem.json,
        ...matchedItem.json,
        listNameHasFound: true,
      },
    });
  } else {
    unmatchedResults.push({
      json: {
        ...prevItem.json,
        listNameHasFound: false,
      },
    });
  }
}

// If at least one match was found anywhere in the batch, only return matches.
// Only return false items if NOTHING matched at all.
const results = matchedResults.length > 0 ? matchedResults : unmatchedResults;

return results;

// Get all items from the previous node
const items = $input.all();

// Check if at least one item has hasTask: true
const hasTaskConfirm = items.some(item => item.json.hasTask === true);

// Add the hasTaskConfirm field to every item and return them
return items.map(item => {
  return {
    json: {
      ...item.json,
      hasTaskConfirm
    }
  };
});

// Get all input items
const items = $input.all();

// Helper to check if body.content is non-empty
const hasContent = (item) => {
  const content = item.json.body?.content;
  return typeof content === 'string' && content.trim().length > 0;
};

// Find items that have content
const itemsWithContent = items.filter(hasContent);

if (itemsWithContent.length > 0) {
  // At least one match found — return only the matched items
  return itemsWithContent.map(item => ({
    json: {
      ...item.json,
      hasNotes: true
    }
  }));
} else {
  // No matches at all — return everything with hasNotes: false
  return items.map(item => ({
    json: {
      ...item.json,
      hasNotes: false
    }
  }));
}

// Pull data from the "ABDUL: IMPORTANT FIELDS" node
const abdulData = $('ABDUL: IMPORTANT FIELDS').all().map(item => item.json);
const metadata = abdulData.length === 1 ? abdulData[0] : abdulData;

// Helper to convert a Graph dateTime object to Asia/Manila
function toManila(dateTimeObj) {
  if (!dateTimeObj || !dateTimeObj.dateTime) return null;

  const converted = DateTime.fromISO(dateTimeObj.dateTime, {
    zone: dateTimeObj.timeZone || 'UTC',
  }).setZone('Asia/Manila');

  return {
    dateTime: converted.toFormat("yyyy-MM-dd'T'HH:mm:ss.SSS") + '0000', // matches Graph's 7-digit fraction
    timeZone: 'Asia/Manila',
  };
}

const items = $input.all();

return items.map(item => {
  const data = { ...item.json };

  // Strip out fields you don't want
  delete data['@odata.etag'];
  delete data['id'];
  delete data['categories']
  delete data['checklistItems@odata.context']
  delete data['hasTask'];
  delete data['hasTaskConfirm'];
  delete data['hasNotes'];

  // Normalize dueDateTime / completedDateTime (or set null if missing)
  data.dueDateTime = toManila(data.dueDateTime);
  data.completedDateTime = toManila(data.completedDateTime);

  // Append metadata from the earlier node
  data.metadata = metadata;

  return { json: data };
});

return [{
  json: {
    username: $input.all()[0].json.metadata.username,
    list_name: $input.all()[0].json.metadata.list_name,
    tasks: $input.all().map(item => item.json)
  }
}];

