    "notes": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "index": { "type": "number", "description": "Position of this task in the original input tasks array, 0-based" },
          "title": { "type": "string" },
          "original": { "type": "string" },
          "ai_note": { "type": "string" }
        },
        "required": ["index", "title", "original", "ai_note"]
      }
    }
  },
  "required": ["username", "list_name", "summary", "notes"]
}

