}

// Normalize input
let lists = [];
const allItems = $input.all();
if (allItems.length === 1 && Array.isArray(allItems[0].json)) {
  lists = allItems[0].json;
} else {
  lists = allItems.map(i => i.json);
}

const output = [];

for (const list of lists) {
  const { username, list_name, summary, tasks = [] } = list;

  let text = '';
  const styleRequests = []; // everything except insertText / insertTable / default font
  let tableInsertIndex = null;

  function addParts(parts, opts = {}) {
    const lineStart = 1 + text.length;
    let cursor = lineStart;
    for (const p of parts) {
      text += p.text;
      const pStart = cursor;
      const pEnd = cursor + p.text.length;
      if (p.bold) {
        styleRequests.push({ updateTextStyle: { range: { startIndex: pStart, endIndex: pEnd }, textStyle: { bold: true }, fields: 'bold' } });
      }
      if (p.italic) {
        styleRequests.push({ updateTextStyle: { range: { startIndex: pStart, endIndex: pEnd }, textStyle: { italic: true }, fields: 'italic' } });
      }
      cursor = pEnd;
    }
    text += '\n';
    const lineEnd = 1 + text.length;
    if (opts.heading) {
      styleRequests.push({
        updateParagraphStyle: {
          range: { startIndex: lineStart, endIndex: lineEnd },
          paragraphStyle: { namedStyleType: opts.heading },
          fields: 'namedStyleType'
        }
      });
    }
    return { start: lineStart, end: lineEnd };
  }

  function addLine(str, opts = {}) {
    return addParts([{ text: str, bold: opts.bold, italic: opts.italic }], opts);
  }

  function blankLine() { text += '\n'; }

  // Title — HEADING_2, bold, 32pt
  const titleRange = addLine(`MS To Do Notes — ${list_name}`, { heading: 'HEADING_2' });
  styleRequests.push({
    updateTextStyle: {
      range: { startIndex: titleRange.start, endIndex: titleRange.end - 1 }, // exclude trailing \n
      textStyle: { bold: true, fontSize: { magnitude: 32, unit: 'PT' } },
      fields: 'bold,fontSize'
    }
  });

  // Helper: HEADING_3 section title — black, 20pt
 function addSectionHeading(str) {
  const r = addLine(str, { heading: 'HEADING_3' });
  styleRequests.push({
    updateTextStyle: {
      range: { startIndex: r.start, endIndex: r.end - 1 },
      textStyle: {
        bold: true,
        fontSize: { magnitude: 20, unit: 'PT' },
        foregroundColor: { color: { rgbColor: { red: 0, green: 0, blue: 0 } } }
      },
      fields: 'bold,fontSize,foregroundColor'
    }
  });
  return r;
}

  // Owner / Date
  const today = formatUtcToManila(new Date().toISOString());
  addParts([{ text: 'Owner: ', bold: true }, { text: username }]);
  addParts([{ text: 'Date: ', bold: true }, { text: today }]);
  blankLine();

  // Summary
  addSectionHeading('Summary');
  addLine(summary);
  blankLine();

  // Task Overview — table goes here
  addSectionHeading('Task Overview');
  tableInsertIndex = 1 + text.length; // table will be inserted at this point
  addLine('(Times shown in Asia/Manila timezone)', { italic: true });
  blankLine();

  // AI-Generated Notes
  addSectionHeading('AI-Generated Notes');
  tasks.forEach((t, i) => {
    addParts([{ text: `${i + 1}. ${t.title}`, bold: true }]);
    addParts([{ text: 'Original: ', bold: true }, { text: (t.body?.content || '').trim() }]);
    addParts([{ text: 'AI Note: ', bold: true }, { text: t.body?.ai_note || '' }]);

    if (t.checklistItems && t.checklistItems.length > 0) {
      addLine('Checklist progress:');
      const bulletStart = 1 + text.length;
      t.checklistItems.forEach(c => addLine(`${c.displayName} — ${c.isChecked ? 'Done' : 'Pending'}`));
      const bulletEnd = 1 + text.length;
      styleRequests.push({
        createParagraphBullets: {
          range: { startIndex: bulletStart, endIndex: bulletEnd },
          bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE'
        }
      });
    }
    blankLine();
  });

  // Default body font size — 12pt across all inserted text, applied BEFORE
  // the heading/bold overrides above are applied so they still win.
  const defaultStyleRequest = {
    updateTextStyle: {
      range: { startIndex: 1, endIndex: 1 + text.length },
      textStyle: { fontSize: { magnitude: 12, unit: 'PT' } },
      fields: 'fontSize'
    }
  };

  const insertTextRequest = { insertText: { location: { index: 1 }, text } };

  // Empty table for the task overview — must be the LAST request so the
  // index math for everything else above stays valid.
  const cols = 6; // Task | Status | Due | Completed | Created | Last Modified
  const insertTableRequest = {
    insertTable: {
      location: { index: tableInsertIndex },
      rows: tasks.length + 1,
      columns: cols
    }
  };

  const requests = [insertTextRequest, defaultStyleRequest, ...styleRequests, insertTableRequest];

  output.push({
    json: {
      documentId: list.metadata?.doc_link_id || list.tasks?.[0]?.metadata?.doc_link_id || null,
      username,
      list_name,
      tasks, // carried forward for phase 2
      requests
    }
  });
}

return output;

