// === 1. Get data from the previous node (AI summary/notes node) ===
const aiData = $input.first().json.output;
// === 2. Get data from the previous-previous node ===
// Replace 'AGGREGATE DATA' with the exact name of that node in your workflow
const aggData = $('MIGUEL: AGGREGATE DATA').first().json;
const username = aggData.username;
const listName = aggData.list_name;
const summary = aiData.summary;
const notes = aiData.notes || [];
// Build lookup maps for safe matching
const notesByIndex = {};
const notesByTitle = {};
notes.forEach(note => {
  notesByIndex[note.index] = note;
  if (note.title) {
    notesByTitle[note.title.trim().toLowerCase()] = note;
  }
});
const tasks = (aggData.tasks || []).map((task, idx) => {
  const taskTitleKey = (task.title || '').trim().toLowerCase();
  // Try index match first
  let matchedNote = notesByIndex[idx];
  // Verify the index match actually has the same title.
  // If it doesn't match (or is missing), fall back to matching by title.
  if (!matchedNote || (matchedNote.title || '').trim().toLowerCase() !== taskTitleKey) {
    matchedNote = notesByTitle[taskTitleKey] || matchedNote || null;
  }
  const aiNote = matchedNote ? matchedNote.ai_note : null;
  // Extract doc_link_id from the Google Docs URL
  const docLink = task.metadata?.doc_link || '';
  const idMatch = docLink.match(/\/d\/([a-zA-Z0-9_-]+)/);
  const docLinkId = idMatch ? idMatch[1] : null;
  return {
    importance: task.importance,
    isReminderOn: task.isReminderOn,
    status: task.status,
    title: task.title,
    createdDateTime: task.createdDateTime,
    lastModifiedDateTime: task.lastModifiedDateTime,
    hasAttachments: task.hasAttachments,
    body: {
      content: task.body?.content,
      contentType: task.body?.contentType,
      ai_note: aiNote
    },
    checklistItems: task.checklistItems || [],
    dueDateTime: task.dueDateTime,
    completedDateTime: task.completedDateTime,
    metadata: {
      list_name: task.metadata?.list_name,
